WITH t1 AS (SELECT SECCODE, INDX_SNAME, LCLOSE FROM INDX_MKT WHERE SECCODE = '000016' AND TRADEDATE >= '2025-01-01' AND TRADEDATE <= '2025-12-31' AND LCLOSE IS NOT NULL AND ISVALID = 1 ORDER BY TRADEDATE ASC LIMIT 1), t2 AS (SELECT SECCODE, TCLOSE FROM INDX_MKT WHERE SECCODE = '000016' AND TRADEDATE >= '2025-01-01' AND TRADEDATE <= '2025-12-31' AND TCLOSE IS NOT NULL AND ISVALID = 1 ORDER BY TRADEDATE DESC LIMIT 1) SELECT t1.INDX_SNAME AS `指数名称`, t1.SECCODE AS `指数代码`, ROUND((t2.TCLOSE / t1.LCLOSE - 1) * 100, 2) AS `2025年涨跌幅(%)` FROM t1 JOIN t2 ON t1.SECCODE = t2.SECCODE;
200
